    [Fact]
    public async Task UmlautCaseInsensitiveSearch_RevealsAsciiOnlyLowerBug()
    {
        var category = new Category { Id = "CU", Name = "UmlautKat" };
        var subcategory = new Subcategory { Id = "SU1", Name = "UmlautSub", CategoryId = "CU" };
        _context.Categories.Add(category);
        _context.Subcategories.Add(subcategory);
        _context.Products.Add(new Product { Id = "PU1", Name = "Ölkanne", Description = "Kanne für Öl", SubcategoryId = "SU1" });
