                : query.OrderBy(p => p.Name).ThenBy(p => p.Id),
            _ => query.OrderBy(p => p.Id)
        };

        var skip = (long)(page - 1) * PageSize;

        var items = page < 1 || skip > int.MaxValue
            ? new List<Product>()
            : await query.Skip((int)skip).Take(PageSize).ToListAsync(ct);

